import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"使用内置库","description":"区分工程内置关系库、时序库、实时库和消息中心，找到对应工作台并理解配置与运行的边界。","frontmatter":{"title":"使用内置库","description":"区分工程内置关系库、时序库、实时库和消息中心，找到对应工作台并理解配置与运行的边界。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/builtin-stores.md","filePath":"zh/使用指南/使用内置库.md"}'),i={name:"zh/guide/builtin-stores.md"};function o(s,t,h,n,l,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="使用内置库" tabindex="-1">使用内置库 <a class="header-anchor" href="#使用内置库" aria-label="Permalink to &quot;使用内置库&quot;">​</a></h1><p>内置库在 **“数据中心” → “接入源”**中使用。它们由平台按工程管理，无需像外部数据库那样填写服务器地址和账号。</p><p>这不表示本机电脑上自动安装了一套数据库，也不表示工程数据已经备份或正式部署。</p><h2 id="_1-按用途选择" tabindex="-1">1. 按用途选择 <a class="header-anchor" href="#_1-按用途选择" aria-label="Permalink to &quot;1. 按用途选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内置类型</th><th>常见用途</th></tr></thead><tbody><tr><td>关系库</td><td>业务表、表单记录和普通 SQL 查询</td></tr><tr><td>时序库</td><td>数据点历史、趋势与聚合</td></tr><tr><td>实时库</td><td>当前值、短期状态和缓存</td></tr><tr><td>消息中心</td><td>设备消息、模拟数据和订阅</td></tr></tbody></table><p>先查看已有连接，避免为同一用途重复创建。确需新增且页面允许时，点击 <strong>“新建连接”</strong>，在“内置运行库”选择类型，填写名称及该类型提供的选项，再点击 <strong>“创建连接”</strong>。</p><p>不要填写或猜测平台内部数据库地址、库名、账号和密码。</p><h2 id="_2-打开对应工作台" tabindex="-1">2. 打开对应工作台 <a class="header-anchor" href="#_2-打开对应工作台" aria-label="Permalink to &quot;2. 打开对应工作台&quot;">​</a></h2><p>找到所需内置接入源并打开。不同类型的工作台不同：</p><ul><li>关系库和时序库使用查询相关工作台，按实际结构选择表或已保存查询。</li><li>实时库使用当前值相关工作台，按业务安排配置和查看数据。</li><li>消息中心使用消息相关工作台，订阅或发布前先核对主题与影响。</li></ul><p>先做一项已获准的小操作，保存后重新读取结果。不要为了熟悉界面向真实业务主题发送测试消息或直接清空业务表。</p><h2 id="_3-查询与输出分别检查" tabindex="-1">3. 查询与输出分别检查 <a class="header-anchor" href="#_3-查询与输出分别检查" aria-label="Permalink to &quot;3. 查询与输出分别检查&quot;">​</a></h2><p>在查询工作台中，可使用 **“新建查询”**准备 SQL，执行前先核对目标库和语句。不要把创建、更新、删除数据的语句当成只读预览。</p><p>准备给页面、计算或报警使用时，按工作台的 **“输出配置”**检查结果类型和提取规则，再使用 <strong>“保存并生成数据点”</strong>（已有点时为“保存并更新数据点”）。普通查询保存和执行不等于点已生成，完整步骤见<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 数据点指南</a>。</p><p>到<a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a>核对生成的点、来源和开发态值，再安排页面或业务使用。</p><h2 id="_4-系统资源与数据保护" tabindex="-1">4. 系统资源与数据保护 <a class="header-anchor" href="#_4-系统资源与数据保护" aria-label="Permalink to &quot;4. 系统资源与数据保护&quot;">​</a></h2><p>系统接入源可能不提供编辑或删除按钮，这是保护行为，不是加载失败。不要通过改文件、重建平台或删除服务器目录绕过。</p><p>工程归档导入不等于恢复全部内置业务数据；导入后内置业务库会按配置重建为空库。需要备份与恢复时，应由数据负责人另行安排。</p><p>正式运行仍依赖运行环境中的相应服务。开发工作台能打开，不能证明所有运行环境已经准备好。</p><p>下一步：<a href="/induframe-docs/zh/guide/access-sources.html">管理接入源</a> · <a href="/induframe-docs/zh/guide/datapoints.html">查看数据点</a>。</p>',20)])])}const u=a(i,[["render",o]]);export{c as __pageData,u as default};
